// STRUCTURE DATA v2.2 (determinista, sin IA)
// Entrada: item del Webhook ({ headers, params, query, body }) o una fila plana.
// BLOQUEANTES (valid=false -> rechazada y registrada): lead_id, name, email válido, consentimiento RGPD.
// BLANDOS (event_type, event_date, guests): nunca bloquean. Si faltan o vienen sucios
// van a missing_fields / dirty_fields y, si hay texto que leer, a ai_fields (plan B).
// La IA nunca repara lead_id, name ni email.
// v2.1: placeholders ("NA", "NO", "0", "indiferente"...) se blanquean SOLO en campos blandos de texto;
// una zona vacía con texto que leer se manda a la IA (preferred_location en ai_fields).
// v2.2: sin gdpr_consent el lead no se procesa: issue 'no_gdpr_consent', valid=false, no pasa por la IA.

const YES = ['yes', 'true', '1', 'si', 'sí', 'y', 'on'];
const PLACEHOLDER = /^(n\/a|n\.a\.|no\s*s[eé]|ns\/?nc|ninguno|ninguna|none|null|undefined|unknown|tbd|tba|por\s+definir|sin\s+definir|pendiente|\?+|-+|\.+)$/i;

const parseDate = (t) => {
  if (!t) return { value: '', status: 'missing' };
  let y, m, d, mt;
  if ((mt = t.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:[T\s].*)?$/))) { y = +mt[1]; m = +mt[2]; d = +mt[3]; }
  else if ((mt = t.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{4})$/))) { d = +mt[1]; m = +mt[2]; y = +mt[3]; } // día primero (ES/CA)
  else return { value: '', status: 'dirty' };
  const dt = new Date(Date.UTC(y, m - 1, d));
  if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== m - 1 || dt.getUTCDate() !== d) return { value: '', status: 'dirty' };
  return { value: dt.toISOString().slice(0, 10), status: 'ok' };
};

const parseNum = (t) => {
  if (!t) return { value: null, status: 'missing' };
  const tokens = t.match(/\d[\d.,]*/g);
  if (!tokens || tokens.length !== 1) return { value: null, status: 'dirty' }; // rangos, textos sin cifra
  let s = tokens[0].replace(/[.,]+$/, '');
  if (/^\d{1,3}(\.\d{3})+(,\d+)?$/.test(s)) s = s.replace(/\./g, '').replace(',', '.'); // 3.000,50
  else if (/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(s)) s = s.replace(/,/g, '');               // 3,000.50
  else s = s.replace(',', '.');
  const v = Number(s);
  return Number.isFinite(v) ? { value: v, status: 'ok' } : { value: null, status: 'dirty' };
};

// Solo para campos blandos de texto (nunca para name, email, lead_id ni consentimientos)
const PLACEHOLDER_SOFT = /^(na|no|nope|nada|0+|sin\s+zona|cualquiera|cualquier\s+sitio|cualquier\s+zona|indiferente|da\s+igual|me\s+da\s+igual)$/i;
const SOFT_TEXT = ['preferred_location', 'event_type', 'company', 'phone'];

const out = [];

for (const item of $input.all()) {
  let r = item.json.body ?? item.json;
  if (typeof r === 'string') { try { r = JSON.parse(r); } catch (e) { r = {}; } }
  r = r || {};

  const get = (k) => {
    const v = (r[k] ?? '').toString().replace(/\s+/g, ' ').trim();
    return (PLACEHOLDER.test(v) || (SOFT_TEXT.includes(k) && PLACEHOLDER_SOFT.test(v))) ? '' : v;
  };
  const getText = (k) => { // conserva saltos de línea (transcripciones)
    const v = (r[k] ?? '').toString().trim();
    return PLACEHOLDER.test(v) ? '' : v;
  };

  const date = parseDate(get('event_date'));
  const guestsP = parseNum(get('guests'));
  if (guestsP.status === 'ok' && !(Number.isInteger(guestsP.value) && guestsP.value >= 1 && guestsP.value <= 2000)) {
    guestsP.status = 'dirty'; guestsP.value = null;
  }
  const budgetP = parseNum(get('budget_eur'));
  if (budgetP.status === 'ok' && !(budgetP.value > 0 && budgetP.value <= 10000000)) {
    budgetP.status = 'dirty'; budgetP.value = null;
  }
  const eventType = get('event_type');

  const lead = {
    lead_id: get('lead_id'),
    created_at: Number.isNaN(Date.parse(get('timestamp'))) ? new Date().toISOString() : get('timestamp'),
    received_at: new Date().toISOString(),
    name: get('name'),
    email: get('email').toLowerCase(),
    company: get('company'),
    phone: get('phone'),
    preferred_location: get('preferred_location'),
    event_type: eventType,
    event_date: date.value,
    guests: guestsP.value,
    budget_eur: budgetP.value,
    message: getText('message'),
    conversation: getText('conversation'),
    gdpr_consent: YES.includes(get('gdpr_consent').toLowerCase()),
    marketing_consent: YES.includes(get('marketing_consent').toLowerCase()),
    raw: { event_date: get('event_date'), guests: get('guests'), budget_eur: get('budget_eur') },
  };

  // Bloqueantes
  const issues = [];
  if (!lead.lead_id) issues.push('lead_id');
  if (!lead.name) issues.push('name');
  if (!lead.email) issues.push('email');
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(lead.email)) issues.push('invalid_email');
  if (!lead.gdpr_consent) issues.push('no_gdpr_consent');

  // Blandos
  const status = { event_type: eventType ? 'ok' : 'missing', event_date: date.status, guests: guestsP.status, budget_eur: budgetP.status };
  const missing_fields = ['event_type', 'event_date', 'guests'].filter((k) => status[k] !== 'ok');
  const dirty_fields = ['event_date', 'guests', 'budget_eur'].filter((k) => status[k] === 'dirty');
  status.preferred_location = lead.preferred_location ? 'ok' : 'missing';
  const ai_candidates = [...new Set([...missing_fields, ...dirty_fields, ...(lead.preferred_location ? [] : ['preferred_location'])])];
  const sourceText = lead.conversation + lead.message + lead.raw.event_date + lead.raw.guests + lead.raw.budget_eur;

  lead.issues = issues;
  lead.valid = issues.length === 0;
  lead.field_status = status;
  lead.missing_fields = missing_fields;
  lead.dirty_fields = dirty_fields;
  lead.ai_fields = sourceText.length > 0 ? ai_candidates : [];
  lead.ai_needed = lead.valid && lead.ai_fields.length > 0;

  out.push({ json: lead });
}

return out;

// ROUTING BY LOCATION v2 (determinista, sin IA)
// Lee Spaces, Reps y Settings de la hoja "IE007 – Database" (nodos 'Database – ...').
// Los datos y las reglas viven en la hoja, no en el código.
// La IA nunca calcula fechas ni aforos: este nodo los calcula y los pasa como hechos.
// Sin zona reconocida el lead NO se asigna por aforo: va a 'unassigned' con motivo y needs_review.

const rows = (name) => $(name).all().map((i) => i.json);
const spaces = rows('Database – Spaces');
const reps = rows('Database – Reps');
const settingsRows = rows('Database – Settings');

const isTrue = (v) => String(v).trim().toLowerCase() === 'true';
const settings = {};
for (const r of settingsRows) if (r.key) settings[String(r.key).trim()] = r.value;
for (const k of ['high_fit_min_days', 'low_fit_max_days']) if (settings[k] !== undefined) settings[k] = Number(settings[k]);

// Normaliza: minúsculas, sin acentos y sin signos ni espacios ("Poble Nou" -> "poblenou", "Gràcia" -> "gracia")
const norm = (s) => (s || '').toString().toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]/g, '');

const activeSpaces = spaces
  .filter((s) => s.space_id && isTrue(s.active))
  .map((s) => ({
    space_id: s.space_id,
    space: s.space,
    max_guests: Number(s.max_guests),
    rep_id: s.rep_id,
    aliases: String(s.zone_aliases || '').split('|').map(norm).filter((a) => a.length >= 3),
  }));

const repById = {};
for (const r of reps) if (r.rep_id && isTrue(r.active)) repById[r.rep_id] = r;
const defaultRep = repById[settings.default_rep_id] || repById['default'] || Object.values(repById)[0];
if (!defaultRep) throw new Error('Routing v2: no hay ningún comercial activo en la hoja Reps');

const todayMs = Date.parse(new Date().toISOString().slice(0, 10) + 'T00:00:00Z');
const out = [];

$('Merge and validate').all().forEach((item, idx) => {
  const lead = item.json;
  const zone = norm(lead.preferred_location);
  const guests = Number.isFinite(lead.guests) && lead.guests > 0 ? lead.guests : null;
  const fits = (s) => guests === null || s.max_guests >= guests;

  const inZone = zone ? activeSpaces.filter((s) => s.aliases.some((a) => zone.includes(a))) : [];
  let match = null;
  let route;
  let review_reason = null;

  if (!zone) {
    route = 'unassigned'; review_reason = 'no_location';
  } else if (inZone.length === 0) {
    route = 'unassigned'; review_reason = 'unknown_location'; // texto que no es ninguna zona nuestra ("NA", "0", "Sants"...)
  } else {
    match = inZone.find(fits) || null;
    if (match) {
      route = 'location_match';
    } else {
      match = activeSpaces.filter(fits).sort((a, b) => a.max_guests - b.max_guests)[0] || null;
      if (match) route = 'capacity_fallback';
      else { route = 'unassigned'; review_reason = 'no_space_fits'; }
    }
  }

  const rep = (match && repById[match.rep_id]) || defaultRep;
  const days = lead.event_date ? Math.round((Date.parse(lead.event_date + 'T00:00:00Z') - todayMs) / 86400000) : null;

  out.push({
    json: {
      ...lead,
      route,
      needs_review: route === 'unassigned',
      review_reason,
      assigned_space: match ? match.space : 'To be defined by the events team',
      space_max_guests: match ? match.max_guests : null,
      assigned_rep_id: rep.rep_id,
      assigned_rep_name: rep.name,
      assigned_rep_email: rep.email,
      calendly_link: rep.calendly,
      settings,
      facts: {
        days_until_event: days,
        event_in_past: days !== null && days < 0,
        capacity_ok: match && guests !== null ? guests <= match.max_guests : null,
        budget_stated: lead.budget_eur !== null && lead.budget_eur !== undefined,
        location_matched: route === 'location_match',
        missing_fields: lead.missing_fields || [],
      },
    },
    pairedItem: { item: idx },
  });
});

return out;

