parameters.jsCode:
// MERGE & VALIDATE (determinista)
// Recibe: (a) items del Information Extractor ({ output: {...} }) y (b) leads limpios de la rama "AI needed? = false".
// Regla: la IA propone, el código decide. Nunca pisa un valor limpio y valida cada campo antes de aceptarlo.

const FIELDS = ['event_type', 'event_date', 'guests', 'budget_eur', 'preferred_location'];
const isEmpty = (v) => v === null || v === undefined || v === '';

const todayStr = new Date().toISOString().slice(0, 10);
const limit = new Date(); limit.setUTCFullYear(limit.getUTCFullYear() + 3);
const limitStr = limit.toISOString().slice(0, 10);

const normNum = (tok) => {
  let s = String(tok).replace(/[.,]+$/, '');
  if (/^\d{1,3}(\.\d{3})+(,\d+)?$/.test(s)) s = s.replace(/\./g, '').replace(',', '.');
  else if (/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(s)) s = s.replace(/,/g, '');
  else s = s.replace(',', '.');
  const v = Number(s);
  return Number.isFinite(v) ? v : null;
};

// Rango explícito "entre A y B", "A-B", "A a B": invitados -> máximo, presupuesto -> mínimo.
const rangeFromRaw = (raw, field) => {
  const text = String(raw || '');
  const tokens = text.match(/\d[\d.,]*/g) || [];
  if (tokens.length !== 2) return null;
  if (!/(\d[\d.,]*)\s*(?:-|–|—|a|y|e|hasta|to|and)\s*(\d[\d.,]*)/i.test(text)) return null;
  const nums = tokens.map(normNum);
  if (nums.some((n) => n === null)) return null;
  return field === 'guests' ? Math.max(...nums) : Math.min(...nums);
};

const clean = (field, value) => {
  switch (field) {
    case 'event_date': {
      const s = String(value).trim();
      const m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
      if (!m) return { ok: false, reason: 'formato_fecha' };
      const dt = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
      if (dt.getUTCFullYear() !== +m[1] || dt.getUTCMonth() !== +m[2] - 1 || dt.getUTCDate() !== +m[3]) return { ok: false, reason: 'fecha_inexistente' };
      if (s < todayStr) return { ok: false, reason: 'fecha_pasada' };
      if (s > limitStr) return { ok: false, reason: 'fecha_demasiado_lejana' };
      return { ok: true, value: s };
    }
    case 'guests': {
      const n = Number(value);
      if (!Number.isInteger(n) || n < 1 || n > 2000) return { ok: false, reason: 'invitados_fuera_de_rango' };
      return { ok: true, value: n };
    }
    case 'budget_eur': {
      const n = Number(value);
      if (!Number.isFinite(n) || n <= 0 || n > 10000000) return { ok: false, reason: 'presupuesto_fuera_de_rango' };
      return { ok: true, value: n };
    }
    case 'event_type':
    case 'preferred_location': {
      const s = String(value).replace(/[\u0000-\u001f<>{}]/g, ' ').replace(/\s+/g, ' ').trim();
      const max = field === 'event_type' ? 60 : 40;
      if (!s || s.length > max) return { ok: false, reason: 'texto_vacio_o_largo' };
      return { ok: true, value: s };
    }
    default:
      return { ok: false, reason: 'campo_no_permitido' };
  }
};

const results = [];
let originals = null;
let aiIdx = 0;

for (const item of $input.all()) {
  const j = item.json;
  const isAi = j.output !== undefined && j.lead_id === undefined;

  // Rama sin IA: pasa tal cual con la misma forma de salida.
  if (!isAi) {
    results.push({ json: { ...j, ai_ran: false, ai_assisted_fields: [], ai_rejected: [] } });
    continue;
  }

  // Rama IA: recupera el lead original (misma posición que en la entrada del extractor).
  if (!originals) originals = $('AI needed?').all(0);
  const orig = originals[aiIdx++];
  if (!orig) throw new Error('Merge & validate: no se encuentra el lead original para el item ' + (aiIdx - 1));

  const lead = JSON.parse(JSON.stringify(orig.json));
  const ai = j.output && typeof j.output === 'object' ? j.output : {};

  const wanted = new Set([
    ...(lead.ai_fields || []),
    ...(isEmpty(lead.preferred_location) ? ['preferred_location'] : []),
    ...(isEmpty(lead.budget_eur) ? ['budget_eur'] : []),
  ]);

  const assisted = [];
  const rejected = [];

  for (const f of FIELDS) {
    if (!wanted.has(f) || !isEmpty(lead[f])) continue; // nunca pisa un valor limpio

    let value;
    let source;
    const isDirtyNumeric = (f === 'guests' || f === 'budget_eur') && (lead.dirty_fields || []).includes(f);
    const byRule = isDirtyNumeric ? rangeFromRaw(lead.raw && lead.raw[f], f) : null;
    if (byRule !== null) { value = byRule; source = 'rule_range'; }
    else { value = ai[f]; source = 'ai'; }

    if (isEmpty(value)) continue;
    const c = clean(f, value);
    if (!c.ok) { rejected.push({ field: f, value: String(value).slice(0, 80), reason: c.reason }); continue; }

    lead[f] = c.value;
    lead.field_status[f] = source === 'ai' ? 'ai' : 'rule';
    assisted.push({ field: f, source });
  }

  lead.missing_fields = ['event_type', 'event_date', 'guests'].filter((k) => isEmpty(lead[k]));
  lead.dirty_fields = (lead.dirty_fields || []).filter((k) => isEmpty(lead[k]));
  lead.ai_ran = true;
  lead.ai_needed = false;
  lead.ai_assisted_fields = assisted;
  lead.ai_rejected = rejected;

  results.push({ json: lead });
}

return results;

// PROFILE GUARDRAILS v1.2
// La IA propone, el código decide: nivel de ajuste acotado por hechos,
// extras normalizados, validados contra catálogo, texto del cliente y relevancia.

const leads = $('Routing by location').all();
const profiles = $input.all();
if (leads.length !== profiles.length) {
  throw new Error(`Profile guardrails: ${profiles.length} perfiles para ${leads.length} leads. No se pueden emparejar por posición.`);
}

const LEVELS = ['low', 'medium', 'high'];
const BAND = { low: [0, 39], medium: [40, 74], high: [75, 100] };

const stripAccents = (s) => (s ?? '').toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const norm = (s) => stripAccents(s).replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();

// Nombre del extra -> nombre canónico del catálogo (sin tildes, sin paréntesis)
const ALIASES = {
  'catering': 'catering',
  'drinks/bar service': 'drinks/bar service', 'drinks': 'drinks/bar service', 'bar service': 'drinks/bar service', 'bar': 'drinks/bar service',
  'audiovisual equipment': 'audiovisual equipment', 'audiovisual': 'audiovisual equipment', 'av': 'audiovisual equipment', 'av equipment': 'audiovisual equipment',
  'furniture': 'furniture', 'mobiliario': 'furniture',
  'decoration': 'decoration', 'decorations': 'decoration', 'decoracion': 'decoration', 'decor': 'decoration',
  'photography/video': 'photography/video', 'photography': 'photography/video', 'video': 'photography/video', 'photo': 'photography/video',
  'cleaning': 'cleaning', 'limpieza': 'cleaning',
  'security': 'security', 'seguridad': 'security',
  'staff/hosts': 'staff/hosts', 'staff': 'staff/hosts', 'hosts': 'staff/hosts'
};
const canon = (raw) => {
  const k = stripAccents(raw).replace(/\([^)]*\)/g, ' ').replace(/\s+/g, ' ').trim();
  return ALIASES[k] ?? null;
};

// Palabras que debe contener la cita para que el extra tenga sentido
const KEYWORDS = {
  'catering': /\b(catering|cena|cenar|comida|almuerzo|comer|food|dinner|lunch|buffet|aperitiv\w*|coctel\w*|cocktail\w*|brunch|merienda)\b/,
  'drinks/bar service': /\b(bebidas?|drinks?|bar|barra|coctel\w*|cocktails?|vinos?|wine|cata|cerveza\w*|beer|copas?|cava)\b/,
  'audiovisual equipment': /\b(audiovisual\w*|pantalla\w*|screens?|sonido|sound|proyector\w*|projector\w*|microfon\w*|micro|escenario|stage|altavoc\w*|speakers?)\b/,
  'furniture': /\b(mesas?|sillas?|taules?|cadires?|tables?|chairs?|mobiliario|furniture|muebles|sofas?)\b/,
  'decoration': /\b(decorac\w*|decoration\w*|decor|flores|flowers|globos|balloons|ambientacion|ambience)\b/,
  'photography/video': /\b(fotos?|foto\w*|photo\w*|video\w*|fotograf\w*|camara\w*|filmacion)\b/,
  'cleaning': /\b(limpieza|limpiar|clean\w*)\b/,
  'security': /\b(seguridad|security|vigilan\w*|guardia\w*)\b/,
  'staff/hosts': /\b(personal|staff|azafat\w*|hosts?|acogida|camarer\w*|waiters?|recepcion\w*|coordinador\w*)\b/
};
// El photobooth no es un servicio de fotografía/vídeo del catálogo
const hasKeyword = (name, text) => KEYWORDS[name].test(text.replace(/\b(photo ?booth|fotomaton\w*)\b/g, ' '));

// Una cita es válida si aparece en el texto del cliente (o >=60% de sus palabras de 4+ letras aparecen).
const grounded = (ev, source) => {
  if (!ev) return false;
  if (source.includes(ev)) return true;
  const tokens = ev.split(' ').filter((t) => t.length >= 4);
  if (tokens.length === 0) return false;
  const hits = tokens.filter((t) => source.includes(t)).length;
  return hits / tokens.length >= 0.6;
};

// Candidatos de cita: texto fuera de paréntesis, contenido entre paréntesis y fragmentos entre comillas
const evidenceCandidates = (raw) => {
  const s = (raw ?? '').toString();
  const parts = [s.replace(/\([^)]*\)/g, ' ')];
  for (const m of s.matchAll(/\(([^)]*)\)/g)) parts.push(m[1]);
  for (const m of s.matchAll(/["“‘']([^"”’']{4,})["”’']/g)) parts.push(m[1]);
  return [...new Set(parts.map(norm).filter(Boolean))];
};

return profiles.map((p, i) => {
  const lead = leads[i].json;
  const out = p.json.output ?? {};
  const facts = lead.facts ?? {};
  const settings = lead.settings ?? {};
  const lowMax = Number(settings.low_fit_max_days ?? 7);
  const highMin = Number(settings.high_fit_min_days ?? 14);
  const days = facts.days_until_event;

  // Tope de nivel según hechos (0 = low, 1 = medium, 2 = high)
  let cap = 2;
  const capReasons = [];
  const limit = (maxRank, reason) => {
    cap = Math.min(cap, maxRank);
    capReasons.push(reason);
  };

  if (facts.event_in_past) limit(0, 'event_in_past');
  else if (typeof days === 'number' && days < lowMax) limit(0, 'event_too_soon');
  else if (typeof days === 'number' && days < highMin) limit(1, 'event_soon');

  if (lead.review_reason === 'no_space_fits') limit(0, 'no_space_fits');
  else if (lead.route === 'unassigned') limit(1, 'space_unassigned');

  if ((facts.missing_fields ?? []).length > 0) limit(1, 'missing_fields');
  if (!facts.budget_stated) limit(1, 'no_budget');

  // Nivel y score: el modelo solo puede bajar el tope, nunca superarlo
  const modelLevel = (out.fit_level ?? '').toString().toLowerCase().trim();
  let modelRank = LEVELS.indexOf(modelLevel);
  const modelInvalid = modelRank === -1;
  if (modelInvalid) modelRank = 1;

  const finalRank = Math.min(modelRank, cap);
  const finalLevel = LEVELS[finalRank];
  const [lo, hi] = BAND[finalLevel];
  const modelScore = Number(out.fit_score);
  const finalScore = Number.isFinite(modelScore)
    ? Math.min(hi, Math.max(lo, Math.round(modelScore)))
    : Math.round((lo + hi) / 2);

  // Extras: catálogo + cita presente en el texto del cliente + cita relevante para el extra
  const source = norm(`${lead.message ?? ''} ${lead.conversation ?? ''}`);
  const extras = [];
  const extrasDropped = [];
  const seen = new Set();
  for (const e of Array.isArray(out.extras) ? out.extras : []) {
    const name = canon(e?.extra);
    if (!name) {
      extrasDropped.push({ extra: e?.extra ?? null, evidence: e?.evidence ?? null, reason: 'not_in_catalogue' });
      continue;
    }
    const groundedCands = evidenceCandidates(e?.evidence).filter((c) => grounded(c, source));
    if (groundedCands.length === 0) {
      extrasDropped.push({ extra: name, evidence: e?.evidence ?? null, reason: 'evidence_not_in_client_text' });
      continue;
    }
    if (!groundedCands.some((c) => hasKeyword(name, c))) {
      extrasDropped.push({ extra: name, evidence: e?.evidence ?? null, reason: 'evidence_does_not_mention_extra' });
      continue;
    }
    if (seen.has(name)) continue;
    seen.add(name);
    extras.push({ extra: name, evidence: e.evidence, confidence: e.confidence ?? 'unknown' });
  }

  return {
    json: {
      ...lead,
      output: {
        ...out,
        fit_level: finalLevel,
        fit_score: finalScore,
        extras,
        extras_dropped: extrasDropped,
        fit_model: { level: modelInvalid ? null : modelLevel, score: Number.isFinite(modelScore) ? modelScore : null },
        fit_overridden: modelInvalid || finalRank !== modelRank || finalScore !== modelScore,
        fit_cap_reasons: capReasons
      }
    },
    pairedItem: { item: i }
  };
});

// BUILD LEAD EMAIL HTML v1.3
// The AI provides two text slots (event_type_en, intro). Both are validated here.
// The extras sentence is built by code from the catalogue names (the AI's extras_note is only logged).
// The space sentence is built by rules from facts (capacity_ok, location_matched).
// Everything else comes from the lead item and the Excel (Spaces, Reps, Settings, Extras).
// Output goes in "auto_reply" so the client address in "email" is preserved.

const leads = $('Auto-reply allowed?').all();
const drafts = $input.all();
if (leads.length !== drafts.length) {
  throw new Error(`Build lead email HTML: ${drafts.length} drafts for ${leads.length} leads. Cannot pair by position.`);
}

const isActive = (v) => v === true || String(v ?? '').trim().toLowerCase() === 'true';

let catalogue;
try {
  catalogue = $('Database – Extras').all().map((i) => i.json).filter((r) => r.extra && isActive(r.active));
} catch (e) {
  throw new Error('Build lead email HTML: node "Database – Extras" was not found or did not run.');
}

let spaceRows = [];
try {
  spaceRows = $('Database – Spaces').all().map((i) => i.json);
} catch (e) {
  spaceRows = [];
}

const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const cap = (s) => (s ? s.charAt(0).toUpperCase() + s.slice(1) : '');
const nice = (s) => cap(String(s ?? '').replace(/\s*\/\s*/g, ' / ').trim());

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const fmtDate = (v) => {
  const raw = String(v ?? '').trim();
  if (!raw) return '';
  const m = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (!m) return raw;
  return `${parseInt(m[3], 10)} ${MONTHS[parseInt(m[2], 10) - 1]} ${m[1]}`;
};

const BANNED = /(€|\$|£|\d\s?(eur|euros)\b|https?:|www\.|@|discount|guarantee|% off)/i;
const cleanSlot = (raw, maxWords, allowedNumbers) => {
  const t = String(raw ?? '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/[*_`#]/g, '')
    .replace(/\s*[—–]\s*/g, ', ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!t) return { text: '', reason: 'empty' };
  if (BANNED.test(t)) return { text: '', reason: 'banned_content' };
  const nums = t.match(/\d+/g) || [];
  if (nums.some((n) => !allowedNumbers.includes(n))) return { text: '', reason: 'unexpected_number' };
  if (t.split(' ').length > maxWords) return { text: '', reason: 'too_long' };
  return { text: t, reason: null };
};

const FONT = 'font-family:Arial,Helvetica,sans-serif;';
const C = {
  navy: '#1F2A44',
  teal: '#0E7C86',
  tealDark: '#0B5F67',
  tealBg: '#E8F4F5',
  text: '#3B4252',
  muted: '#6B7686',
  line: '#E1E7EE',
  panel: '#F4F7FA',
  outer: '#EEF1F5',
  headerSub: '#B9C4D8'
};

return drafts.map((d, i) => {
  const lead = leads[i].json;
  const out = lead.output || {};
  const slotsRaw = d.json.output || {};
  const leadId = lead.lead_id ?? `item ${i}`;

  const space = String(lead.assigned_space ?? '').trim();
  const rep = String(lead.assigned_rep_name ?? '').trim();
  const company = String(lead.settings?.company_name ?? '').trim();
  const calendly = String(lead.calendly_link ?? '').trim();
  const calendlyOk = /^https:\/\/[^\s"'<>]+$/.test(calendly);

  if (!space || !rep || !company) {
    throw new Error(`Build lead email HTML: ${leadId} is missing assigned_space, assigned_rep_name or settings.company_name.`);
  }

  const fallbacks = [];
  const guestsNum = Number(lead.guests);
  const preferred = String(lead.preferred_location ?? '').trim();

  // ---------- AI slot: event_type_en ----------
  const originalType = String(lead.event_type ?? '').trim();
  const typeRaw = String(slotsRaw.event_type_en ?? '').trim().toLowerCase().replace(/\s+/g, ' ');
  let eventType = '';
  if (!typeRaw) {
    fallbacks.push('event_type_en:empty');
  } else if (!/^[a-z]+( [a-z]+){0,3}$/.test(typeRaw)) {
    fallbacks.push('event_type_en:invalid_format');
  } else {
    eventType = typeRaw;
  }
  // eventType is only set when the AI value passed validation (English). The recap falls back to the original text.
  const article = /^[aeiou]/.test(eventType) ? 'an' : 'a';

  // ---------- AI slot: intro ----------
  const dm = String(lead.event_date ?? '').match(/^(\d{4})-(\d{2})-(\d{2})/);
  const allowedIntro = dm ? [String(parseInt(dm[3], 10)), dm[1]] : [];
  if (guestsNum > 0) allowedIntro.push(String(guestsNum));
  const introSlot = cleanSlot(slotsRaw.intro, 45, allowedIntro);
  let intro = introSlot.text;
  if (!intro) {
    intro = eventType
      ? `Thanks for your enquiry about ${article} ${eventType}. Below is a summary of what we understood.`
      : 'Thanks for your enquiry. Below is a summary of what we understood.';
    fallbacks.push(`intro:${introSlot.reason}`);
  }

  // ---------- Extras ----------
  const mentionedNames = (Array.isArray(out.extras) ? out.extras : []).map((e) => String(e.extra ?? '').trim().toLowerCase());
  const mentioned = catalogue.filter((r) => mentionedNames.includes(String(r.extra).trim().toLowerCase()));
  const available = catalogue.filter((r) => !mentionedNames.includes(String(r.extra).trim().toLowerCase()));

  // ---------- Extras sentence (code, exact catalogue names) ----------
  const inSentence = (s) => String(s ?? '').replace(/\s*\/\s*/g, '/').trim().toLowerCase();
  const joinNames = (arr) => (arr.length <= 1 ? arr.join('') : `${arr.slice(0, -1).join(', ')} and ${arr[arr.length - 1]}`);
  const extrasNote = mentioned.length ? `We can help with ${joinNames(mentioned.map((r) => inSentence(r.extra)))}.` : '';

  const first = String(lead.name ?? '').trim().split(/\s+/)[0];
  const greeting = first ? `Hi ${first},` : 'Hi there,';
  const subject = `Your event at ${space}: next step`;
  const preheader = 'Your event enquiry: a summary and the next step.';

  const recap = [
    ['Event type', eventType ? cap(eventType) : (cap(originalType) || 'Event')],
    ['Date', fmtDate(lead.event_date)],
    ['Guests', guestsNum > 0 ? `${guestsNum} ${guestsNum === 1 ? 'guest' : 'guests'}` : ''],
    ['Preferred area', preferred]
  ].filter(([, v]) => v);

  // ---------- Space block (rules, not AI) ----------
  const maxGuests = Number(lead.space_max_guests);
  const spaceRow = spaceRows.find((r) => String(r.space ?? '').trim() === space) || {};
  const spaceInfo = [
    maxGuests > 0 ? `Up to ${maxGuests} guests` : '',
    String(spaceRow.notes ?? '').trim()
  ].filter(Boolean).join(' · ');

  const hasRoom = lead.facts?.capacity_ok === true;
  const areaMatch = lead.facts?.location_matched === true && preferred !== '';
  const areaMiss = lead.facts?.location_matched === false && preferred !== '';
  let spaceText = '';
  if (areaMatch && hasRoom) spaceText = 'It is in the area you asked for and has room for your group.';
  else if (areaMatch) spaceText = 'It is in the area you asked for.';
  else if (areaMiss && hasRoom) spaceText = 'It has room for your group, but it is in a different area from the one you asked for. The team will go through this with you on the call.';
  else if (areaMiss) spaceText = 'It is in a different area from the one you asked for. The team will go through this with you on the call.';
  else if (hasRoom) spaceText = 'It has room for your group.';

  const missing = Array.isArray(lead.facts?.missing_fields) ? lead.facts.missing_fields : [];
  const missingLine = missing.length ? 'A few details are still missing, so the team will confirm them with you on the call.' : '';
  const callLine = calendlyOk
    ? `${rep} from our sales team will call you to go through the details. Pick the time that suits you best.`
    : `${rep} from our sales team will contact you shortly to go through the details.`;
  const callText = [missingLine, callLine].filter(Boolean).join(' ');

  const notice = 'This message was generated automatically from your enquiry. A member of our team will review it and contact you to confirm the details.';

  // ---------- HTML blocks ----------
  const recapHtml = (() => {
    if (!recap.length) return '';
    const rows = [];
    for (let k = 0; k < recap.length; k += 2) {
      const padTop = k === 0 ? 16 : 8;
      const padBottom = k + 2 >= recap.length ? 16 : 8;
      const cell = ([l, v]) => `<td width="50%" valign="top" style="padding:${padTop}px 20px ${padBottom}px 20px;"><div style="${FONT}font-size:12px;color:${C.muted};">${esc(l)}</div><div style="${FONT}font-size:15px;font-weight:bold;color:${C.navy};padding-top:2px;">${esc(v)}</div></td>`;
      rows.push(`<tr>${cell(recap[k])}${recap[k + 1] ? cell(recap[k + 1]) : '<td width="50%"></td>'}</tr>`);
    }
    return `<tr><td style="padding:20px 32px 8px 32px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:${C.panel};border:1px solid ${C.line};border-radius:10px;">${rows.join('')}</table></td></tr>`;
  })();

  const spaceHtml = `<tr><td style="padding:16px 32px 8px 32px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:${C.tealBg};border-left:4px solid ${C.teal};"><tr><td style="padding:16px 20px;"><div style="${FONT}font-size:12px;color:${C.tealDark};">Suggested space</div><div style="${FONT}font-size:18px;font-weight:bold;color:${C.navy};padding:2px 0 4px 0;">${esc(space)}</div>${spaceInfo ? `<div style="${FONT}font-size:13px;color:${C.tealDark};padding-bottom:8px;">${esc(spaceInfo)}</div>` : ''}${spaceText ? `<div style="${FONT}font-size:14px;line-height:22px;color:${C.text};">${esc(spaceText)}</div>` : ''}</td></tr></table></td></tr>`;

  const mentionedHtml = mentioned.length
    ? `<tr><td style="padding:16px 32px 4px 32px;"><div style="${FONT}font-size:12px;color:${C.muted};padding-bottom:8px;">Services you mentioned</div><div>${mentioned.map((r) => `<span style="display:inline-block;background:${C.teal};border-radius:16px;padding:6px 14px;margin:0 8px 8px 0;${FONT}font-size:13px;font-weight:bold;color:#FFFFFF;">${esc(nice(r.extra))}</span>`).join('')}</div>${extrasNote ? `<div style="${FONT}font-size:14px;line-height:22px;color:${C.text};padding-top:2px;">${esc(extrasNote)}</div>` : ''}</td></tr>`
    : '';

  const availableHtml = (() => {
    if (!available.length) return '';
    const card = (r, left) => `<td width="50%" valign="top" style="padding:${left ? '0 6px 12px 0' : '0 0 12px 6px'};"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#FFFFFF;border:1px solid ${C.line};border-radius:8px;"><tr><td style="padding:12px 14px;"><div style="${FONT}font-size:14px;font-weight:bold;color:${C.navy};">${esc(nice(r.extra))}</div>${r.description ? `<div style="${FONT}font-size:12px;line-height:18px;color:${C.muted};padding-top:2px;">${esc(r.description)}</div>` : ''}</td></tr></table></td>`;
    const rows = [];
    for (let k = 0; k < available.length; k += 2) {
      rows.push(`<tr>${card(available[k], true)}${available[k + 1] ? card(available[k + 1], false) : '<td width="50%"></td>'}</tr>`);
    }
    return `<tr><td style="padding:20px 32px 8px 32px;"><div style="${FONT}font-size:16px;font-weight:bold;color:${C.navy};padding-bottom:4px;">You can also add</div><div style="${FONT}font-size:13px;line-height:20px;color:${C.muted};padding-bottom:12px;">Our team can arrange any of these. If something interests you, we can go through it on the call.</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">${rows.join('')}</table></td></tr>`;
  })();

  const buttonHtml = calendlyOk
    ? `<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr><td align="center" bgcolor="${C.teal}" style="background:${C.teal};border-radius:8px;"><a href="${esc(calendly)}" style="display:inline-block;padding:14px 28px;${FONT}font-size:15px;font-weight:bold;color:#FFFFFF;text-decoration:none;">Book a call with ${esc(rep)}</a></td></tr></table>`
    : '';

  const html = `<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><title>${esc(subject)}</title></head><body style="margin:0;padding:0;background:${C.outer};"><div style="display:none;max-height:0;overflow:hidden;opacity:0;color:${C.outer};">${esc(preheader)}</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:${C.outer};"><tr><td align="center" style="padding:24px 12px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:600px;background:#FFFFFF;border-radius:12px;${FONT}">`
    + `<tr><td style="background:${C.navy};padding:22px 32px;border-radius:12px 12px 0 0;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td style="${FONT}font-size:18px;font-weight:bold;color:#FFFFFF;">${esc(company)}</td><td align="right" style="${FONT}font-size:12px;color:${C.headerSub};">Your event enquiry</td></tr></table></td></tr>`
    + `<tr><td style="padding:32px 32px 8px 32px;"><p style="margin:0 0 12px 0;${FONT}font-size:22px;line-height:28px;font-weight:bold;color:${C.navy};">${esc(greeting)}</p><p style="margin:0;${FONT}font-size:15px;line-height:24px;color:${C.text};">${esc(intro)}</p></td></tr>`
    + recapHtml
    + spaceHtml
    + mentionedHtml
    + availableHtml
    + `<tr><td align="center" style="padding:16px 32px 8px 32px;"><p style="margin:0 0 16px 0;${FONT}font-size:15px;line-height:24px;color:${C.text};text-align:left;">${esc(callText)}</p>${buttonHtml}</td></tr>`
    + `<tr><td style="padding:24px 32px 28px 32px;"><div style="${FONT}font-size:14px;line-height:22px;color:${C.text};">Kind regards,<br><span style="font-weight:bold;color:${C.navy};">${esc(rep)}</span><br>${esc(company)}</div></td></tr>`
    + `<tr><td style="background:${C.panel};border-top:1px solid ${C.line};padding:16px 32px;border-radius:0 0 12px 12px;"><div style="${FONT}font-size:12px;line-height:18px;color:${C.muted};">${esc(notice)}</div></td></tr>`
    + `</table></td></tr></table></body></html>`;

  // ---------- Plain-text version ----------
  const textLines = [greeting, '', intro, ''];
  recap.forEach(([l, v]) => textLines.push(`${l}: ${v}`));
  textLines.push('', `Suggested space: ${space}`);
  if (spaceInfo) textLines.push(spaceInfo);
  if (spaceText) textLines.push(spaceText);
  if (mentioned.length) {
    textLines.push('', `Services you mentioned: ${mentioned.map((r) => nice(r.extra)).join(', ')}`);
    if (extrasNote) textLines.push(extrasNote);
  }
  if (available.length) {
    textLines.push('', 'You can also add:');
    available.forEach((r) => textLines.push(`- ${nice(r.extra)}${r.description ? `: ${r.description}` : ''}`));
  }
  textLines.push('', callText);
  if (calendlyOk) textLines.push(`Book a call: ${calendly}`);
  textLines.push('', 'Kind regards,', rep, company, '', notice);

  return {
    json: {
      ...lead,
      auto_reply: {
        to: String(lead.email ?? '').trim(),
        subject,
        html,
        text: textLines.join('\n'),
        slot_fallbacks: fallbacks
      },
      email_ai_slots: slotsRaw
    },
    pairedItem: { item: i }
  };
});

