// BUILD SALES EMAIL HTML v1.1
// No AI writes this email. It is a fixed template filled with data the flow already has:
// lead data, routing facts, the guarded profile (Profile guardrails) and the sentiment (AI – Customer sentiment).
// v1.1: plain language for the sales team. The "why this fit" bullets are written by code from the facts,
// never copied from the AI (its reasons used field names like route or location_match). No codes in the email.
// Output: sales_email (to, subject, html), log_row (Processing log) and sentiment_row (Sentiment log).

const leads = $('Profile guardrails').all();
const sentiments = $input.all();
if (leads.length !== sentiments.length) {
  throw new Error(`Build sales email HTML: ${sentiments.length} sentiment results for ${leads.length} leads. Cannot pair by position.`);
}

const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');
const cap = (s) => (s ? String(s).charAt(0).toUpperCase() + String(s).slice(1) : '');
const clean = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const fmtDate = (v) => {
  const m = String(v ?? '').match(/^(\d{4})-(\d{2})-(\d{2})/);
  return m ? `${parseInt(m[3], 10)} ${MONTHS[parseInt(m[2], 10) - 1]} ${m[1]}` : '';
};
const fmtEur = (v) => (Number.isFinite(Number(v)) && v !== null && v !== '' ? `${Number(v).toLocaleString('en-GB', { maximumFractionDigits: 2 })} EUR` : '');

const REVIEW_LABEL = {
  no_location: 'The client gave no preferred area',
  unknown_location: 'The preferred area is not one of our zones',
  no_space_fits: 'No space can hold this number of guests'
};
const FIELD_LABEL = { event_type: 'Event type', event_date: 'Event date', guests: 'Number of guests', budget_eur: 'Budget', preferred_location: 'Preferred area' };

const FONT = 'font-family:Arial,Helvetica,sans-serif;';
const C = {
  navy: '#1F2A44', teal: '#0E7C86', text: '#3B4252', muted: '#6B7686', line: '#E1E7EE',
  panel: '#F4F7FA', outer: '#EEF1F5', headerSub: '#B9C4D8',
  high: '#1E7F4F', medium: '#B7791F', low: '#B23B3B',
  alertBg: '#FDECEC', alertLine: '#B23B3B', infoBg: '#FFF7E6', infoLine: '#B7791F'
};
const SENT_COLOR = { positive: '#1E7F4F', neutral: '#6B7686', mixed: '#B7791F', negative: '#B23B3B', no_text: '#6B7686' };
const SENTIMENTS = ['positive', 'neutral', 'negative', 'mixed'];

let largestSpace = null;
try {
  const caps = $('Database – Spaces').all().map((r) => Number(r.json.max_guests)).filter((n) => n > 0);
  largestSpace = caps.length ? Math.max(...caps) : null;
} catch (e) {
  largestSpace = null;
}

const now = new Date().toISOString();

return sentiments.map((s, i) => {
  const lead = leads[i].json;
  const p = lead.output || {};
  const facts = lead.facts || {};
  const settings = lead.settings || {};

  // ---------- Auto-reply decision (same rule as the "Auto-reply allowed?" node) ----------
  const rank = { low: 0, medium: 1, high: 2 };
  const min = rank[settings.auto_reply_min_fit ?? 'medium'];
  const autoReply = lead.route !== 'unassigned' && !facts.event_in_past && rank[p.fit_level] >= min;

  // ---------- Sentiment (validated) ----------
  const raw = s.json.output || {};
  const hasText = clean(lead.conversation || lead.message) !== '';
  let sentiment = SENTIMENTS.includes(String(raw.sentiment).toLowerCase()) ? String(raw.sentiment).toLowerCase() : 'neutral';
  let score = Number(raw.score);
  score = Number.isFinite(score) ? Math.max(-1, Math.min(1, Math.round(score * 100) / 100)) : 0;
  let frustration = (Array.isArray(raw.frustration_points) ? raw.frustration_points : []).map(clean).filter(Boolean).slice(0, 5);
  let summary = clean(raw.summary);
  if (!hasText) {
    sentiment = 'no_text'; score = 0; frustration = []; summary = 'The client left no message or conversation to analyse.';
  }

  // ---------- Data for the email ----------
  const level = String(p.fit_level || 'medium');
  const levelColor = C[level] || C.medium;
  const who = clean(lead.company) || clean(lead.name) || 'Unknown client';
  const dateTxt = fmtDate(lead.event_date) || 'date to be confirmed';
  const subject = `${({ high: 'Strong lead', medium: 'Possible lead', low: 'Weak lead' })[level] || 'New lead'}: ${who}, ${dateTxt}`;
  const to = clean(lead.assigned_rep_email);
  const repName = clean(lead.assigned_rep_name) || 'team';

  const alerts = [];
  if (!autoReply) alerts.push('No automatic reply was sent to the client. Please contact them yourself.');
  if (lead.needs_review) alerts.push(`Needs a person to choose the space: ${(REVIEW_LABEL[lead.review_reason] || 'no space could be assigned').toLowerCase()}.`);
  if (facts.event_in_past) alerts.push('The event date is in the past. Check the date with the client.');
  const notices = [];
  if (sentiment === 'negative' || sentiment === 'mixed') notices.push("The client seems frustrated. Read the client's mood section before calling.");
  const aiFields = (Array.isArray(lead.ai_assisted_fields) ? lead.ai_assisted_fields : []).map((f) => FIELD_LABEL[f.field] || f.field).filter(Boolean);
  if (aiFields.length) notices.push(`We took this from the client's message, not from the form, so please confirm it: ${aiFields.join(', ').toLowerCase()}.`);

  const clientRows = [
    ['Name', clean(lead.name)],
    ['Company', clean(lead.company)],
    ['Email', clean(lead.email)],
    ['Phone', clean(lead.phone).replace(/^'/, '')]
  ].filter(([, v]) => v);

  const spaceTxt = lead.route === 'unassigned'
    ? 'To be defined by the events team'
    : `${clean(lead.assigned_space)}${lead.space_max_guests ? ` (up to ${lead.space_max_guests} guests)` : ''}`;
  const eventRows = [
    ['Event type', cap(clean(lead.event_type)) || 'Not stated'],
    ['Date', fmtDate(lead.event_date) ? `${fmtDate(lead.event_date)}${Number.isFinite(facts.days_until_event) ? ` (${facts.days_until_event} days ahead)` : ''}` : 'Not stated'],
    ['Guests', lead.guests ? String(lead.guests) : 'Not stated'],
    ['Budget', fmtEur(lead.budget_eur) || 'Not stated'],
    ['Preferred area', clean(lead.preferred_location) || 'Not stated'],
    ['Suggested space', spaceTxt]
  ];

  // ---------- Why this fit, in plain words (built from facts, not from the AI) ----------
  const guests = Number(lead.guests) > 0 ? Number(lead.guests) : null;
  const area = clean(lead.preferred_location);
  const days = Number.isFinite(facts.days_until_event) ? facts.days_until_event : null;
  const reasons = [];
  if (lead.route === 'location_match') reasons.push(`The suggested space is in the area the client asked for${area ? ` (${area})` : ''}.`);
  else if (lead.route === 'capacity_fallback') reasons.push(`No space in ${area || 'the area they asked for'} is big enough, so we suggest ${clean(lead.assigned_space)} instead.`);
  else if (lead.review_reason === 'no_location') reasons.push('The client did not say where they want the event, so no space is suggested yet.');
  else if (lead.review_reason === 'unknown_location') reasons.push(`The area the client gave (${area}) is not one we cover, so no space is suggested yet.`);
  else if (lead.review_reason === 'no_space_fits') reasons.push(`None of our spaces can hold ${guests} guests${largestSpace ? ` (the largest takes ${largestSpace})` : ''}.`);
  if (lead.route !== 'unassigned') {
    if (guests && lead.space_max_guests) reasons.push(`${guests} guests fit well in a space for up to ${lead.space_max_guests}.`);
    else if (!guests) reasons.push('We do not know how many guests yet.');
  }
  if (facts.event_in_past) reasons.push('The date the client gave has already passed.');
  else if (days === null) reasons.push('There is no event date yet.');
  else if (days < 7) reasons.push(`The event is in ${days} ${days === 1 ? 'day' : 'days'}, very little time to organise it.`);
  else if (days < 14) reasons.push(`The event is in ${days} days, a tight timeline.`);
  else reasons.push(`The event is ${days} days away, enough time to prepare.`);
  reasons.push(lead.budget_eur !== null && lead.budget_eur !== undefined ? `The client has a budget of ${fmtEur(lead.budget_eur)}.` : 'The client has not given a budget.');
  const extras = Array.isArray(p.extras) ? p.extras : [];

  const missing = [...new Set([
    ...(Array.isArray(facts.missing_fields) ? facts.missing_fields : []).map((f) => FIELD_LABEL[f] || f),
    ...(lead.budget_eur === null || lead.budget_eur === undefined ? ['Budget'] : []),
    ...(lead.route === 'unassigned' ? ['Preferred area or space'] : [])
  ])];

  let nextStep;
  if (facts.event_in_past) nextStep = 'Confirm the real event date with the client before anything else.';
  else if (!autoReply) nextStep = `Call the client. They have not received any reply yet.`;
  else if (missing.length) nextStep = `The client has your booking link. On the call, confirm: ${missing.join(', ').toLowerCase()}.`;
  else nextStep = 'The client has your booking link. Prepare a proposal for the suggested space before the call.';

  // ---------- HTML helpers ----------
  const section = (title, inner) => `<tr><td style="padding:16px 32px 4px 32px;"><div style="${FONT}font-size:12px;font-weight:bold;letter-spacing:0.08em;text-transform:uppercase;color:${C.muted};padding-bottom:8px;">${esc(title)}</div>${inner}</td></tr>`;
  const kv = (rows) => `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:${C.panel};border:1px solid ${C.line};border-radius:8px;">${rows.map(([k, v], idx) => `<tr><td width="38%" valign="top" style="padding:8px 14px;${idx ? `border-top:1px solid ${C.line};` : ''}${FONT}font-size:13px;color:${C.muted};">${esc(k)}</td><td valign="top" style="padding:8px 14px;${idx ? `border-top:1px solid ${C.line};` : ''}${FONT}font-size:14px;color:${C.navy};">${esc(v)}</td></tr>`).join('')}</table>`;
  const list = (items) => `<ul style="margin:0;padding:0 0 0 18px;">${items.map((t) => `<li style="${FONT}font-size:14px;line-height:21px;color:${C.text};padding-bottom:4px;">${esc(t)}</li>`).join('')}</ul>`;
  const box = (items, bg, lineColor) => items.length ? `<tr><td style="padding:16px 32px 0 32px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:${bg};border-left:4px solid ${lineColor};"><tr><td style="padding:12px 16px;">${items.map((t) => `<div style="${FONT}font-size:14px;line-height:21px;font-weight:bold;color:${C.navy};">${esc(t)}</div>`).join('')}</td></tr></table></td></tr>` : '';

  const LEVEL_TEXT = { high: 'Strong lead', medium: 'Possible lead', low: 'Weak lead' };
  const fitHtml = `<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr><td style="background:${levelColor};border-radius:14px;padding:5px 12px;${FONT}font-size:13px;font-weight:bold;color:#FFFFFF;">${esc(LEVEL_TEXT[level] || 'Possible lead')} · ${esc(p.fit_score ?? '')}/100</td></tr></table>`
    + `<div style="padding-top:10px;">${list(reasons)}</div>`;

  const sentLabel = { positive: 'Positive', neutral: 'Neutral', negative: 'Unhappy', mixed: 'Mixed', no_text: 'Nothing to read' }[sentiment];
  const sentimentHtml = `<div style="${FONT}font-size:14px;color:${C.text};"><span style="font-weight:bold;color:${SENT_COLOR[sentiment]};">${esc(sentLabel)}</span></div>`
    + (summary ? `<div style="${FONT}font-size:14px;line-height:21px;color:${C.text};padding-top:6px;">${esc(summary)}</div>` : '')
    + (frustration.length ? `<div style="padding-top:8px;">${list(frustration)}</div>` : '');

  const extrasHtml = extras.length
    ? `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border:1px solid ${C.line};border-radius:8px;"><tr>${['Service', "Client's words", 'How sure'].map((h) => `<td style="padding:8px 12px;background:${C.panel};${FONT}font-size:12px;font-weight:bold;color:${C.muted};">${h}</td>`).join('')}</tr>${extras.map((e) => `<tr><td valign="top" style="padding:8px 12px;border-top:1px solid ${C.line};${FONT}font-size:14px;font-weight:bold;color:${C.navy};">${esc(cap(e.extra))}</td><td valign="top" style="padding:8px 12px;border-top:1px solid ${C.line};${FONT}font-size:13px;font-style:italic;color:${C.text};">${esc(clean(e.evidence))}</td><td valign="top" style="padding:8px 12px;border-top:1px solid ${C.line};${FONT}font-size:13px;color:${C.text};">${esc(e.confidence)}</td></tr>`).join('')}</table>`
    : `<div style="${FONT}font-size:14px;color:${C.muted};">None mentioned.</div>`;

  const messageTxt = clean(lead.message);

  const html = `<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><title>${esc(subject)}</title></head><body style="margin:0;padding:0;background:${C.outer};"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:${C.outer};"><tr><td align="center" style="padding:24px 12px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:600px;background:#FFFFFF;border-radius:12px;${FONT}">`
    + `<tr><td style="background:${C.navy};padding:20px 32px;border-radius:12px 12px 0 0;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td style="${FONT}font-size:18px;font-weight:bold;color:#FFFFFF;">New enquiry</td><td align="right" style="${FONT}font-size:12px;color:${C.headerSub};">Internal · ${esc(lead.lead_id)}</td></tr></table></td></tr>`
    + `<tr><td style="padding:24px 32px 0 32px;"><p style="margin:0;${FONT}font-size:15px;line-height:24px;color:${C.text};">Hi ${esc(repName)}, a new enquiry has been assigned to you.</p></td></tr>`
    + box(alerts, C.alertBg, C.alertLine)
    + box(notices, C.infoBg, C.infoLine)
    + section('Next step', `<div style="${FONT}font-size:15px;line-height:22px;font-weight:bold;color:${C.navy};">${esc(nextStep)}</div>`)
    + section('How good is this lead', fitHtml)
    + section('Client', kv(clientRows))
    + section('Event', kv(eventRows))
    + section('Services the client mentioned', extrasHtml)
    + (missing.length ? section('Ask on the call', list(missing)) : '')
    + section("Client's mood", sentimentHtml)
    + (messageTxt ? section("Client's message", `<div style="${FONT}font-size:14px;line-height:21px;font-style:italic;color:${C.text};border-left:3px solid ${C.line};padding-left:12px;">${esc(messageTxt)}</div>`) : '')
    + `<tr><td style="padding:20px 32px 0 32px;"></td></tr>`
    + `<tr><td style="background:${C.panel};border-top:1px solid ${C.line};padding:14px 32px;border-radius:0 0 12px 12px;"><div style="${FONT}font-size:12px;line-height:18px;color:${C.muted};">The lead rating, the services and the client's mood are suggested by AI and checked against our rules. Dates, guests, budget and the suggested space come straight from the enquiry and our database. You make the final call.</div></td></tr>`
    + `</table></td></tr></table></body></html>`;

  return {
    json: {
      lead_id: lead.lead_id,
      sales_email: { to, subject, html },
      log_row: {
        lead_id: lead.lead_id,
        processed_at: now,
        status: lead.needs_review ? 'needs_review' : 'processed',
        issues: [...new Set([...(Array.isArray(p.fit_cap_reasons) ? p.fit_cap_reasons : []), ...(lead.review_reason ? [lead.review_reason] : [])])].join(', '),
        route: lead.route,
        assigned_space: lead.route === 'unassigned' ? '' : clean(lead.assigned_space),
        assigned_rep: clean(lead.assigned_rep_name),
        days_until_event: Number.isFinite(facts.days_until_event) ? facts.days_until_event : '',
        fit_level: level,
        fit_score: p.fit_score ?? '',
        client_auto_reply: autoReply ? 'yes' : 'no',
        model: clean(settings.ai_model)
      },
      sentiment_row: {
        lead_id: lead.lead_id,
        analysed_at: now,
        event_type: clean(lead.event_type),
        sentiment,
        score,
        frustration_points: frustration.join(' | '),
        summary
      }
    },
    pairedItem: { item: i }
  };
});
